cases.script:
description=$(help -d dmsetup)
case "$description" in
  *"Low-level device-mapper control."*) printf 'dmsetup short help description is present\n' ;;
  *) exit 1 ;;
esac

doc=$(help dmsetup)
case "$doc" in
  *"dmsetup ls|info|table|status|deps|targets|version [ARGS...]"*"dmsetup create|load|reload|remove|remove_all|suspend|resume|rename|message|clear|wipe_table ..."*"Mutating commands require root and BASHOS_DMSETUP_ALLOW_MUTATE=1."*) printf 'dmsetup help synopsis and policy are present\n' ;;
  *) exit 1 ;;
esac
